$("#rows").onkeydown = e => {
  const tr = e.target.closest("tr[data-id]"); if (!tr || e.target.matches("input")) return;
  if (e.key === "Enter") { e.preventDefault(); open(tr.dataset.id); }
  if (e.key === " ") { e.preventDefault(); const c = tr.querySelector("[data-sel]"); if (c) { c.checked = !c.checked; c.dispatchEvent(new Event("change", {bubbles: true})); } }
  if (e.key === "ArrowDown" && tr.nextElementSibling) { e.preventDefault(); tr.nextElementSibling.focus(); }
  if (e.key === "ArrowUp" && tr.previousElementSibling) { e.preventDefault(); tr.previousElementSibling.focus(); }
};

