def _img(fmt, size):
    b = io.BytesIO(); Image.new("L", size, 255).save(b, fmt); return b.getvalue()


def test_pixel_bomb_is_rejected_before_decoding(tmp_path, monkeypatch):
    monkeypatch.setattr(imaging, "MAX_PIXELS", 1000)
    svc, c = make(tmp_path, [F("粤B1", "2026-10-10", "08:00", "08:10", "11000", "10000", "1000")])
    r = c.post("/api/v1/records", files={"photo": ("a.png", _img("PNG", (100, 100)), "image/png")}, data={"doc_type": "site_in"})
    assert r.status_code == 422 and "像素太大" in r.json()["error"]["message"]


def test_big_phone_jpeg_is_decoded_small_not_rejected(monkeypatch):
    """手机 48~108MP 的 JPEG 不能被像素上限误伤:按缩小比例解码后再判。"""
    monkeypatch.setattr(imaging, "MAX_PIXELS", 1000)
    im = imaging.normalize(_img("JPEG", (100, 100)), max_side=20)
    assert max(im.size) <= 25


