async function load(keepOpen) {
  syncUrl(); markPreset(); drawViews(); $("#err").hidden = true;
  try {
    if (view === "stats") {
      const p = new URLSearchParams();
  if ($("#f-origin").value) p.set("origin_id", $("#f-origin").value);
      if ($("#f-from").value) p.set("date_from", $("#f-from").value);
      if ($("#f-to").value) p.set("date_to", $("#f-to").value);
      const r = await fetch("__WB_BASE_PATH__/api/v1/stats?" + p);
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      stats = await r.json(); drawStats();
    } else if (view === "recon") {
      const p = new URLSearchParams();
  if ($("#f-origin").value) p.set("origin_id", $("#f-origin").value);
      if ($("#f-from").value) p.set("date_from", $("#f-from").value);
      if ($("#f-to").value) p.set("date_to", $("#f-to").value);
      const r = await fetch("__WB_BASE_PATH__/api/v1/reconciliation?" + p);
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      recon = await r.json(); drawRecon();
    } else {
      const [r, rv] = await Promise.all([fetch("__WB_BASE_PATH__/api/v1/records?" + query({doc_type: view, limit: LIMIT})),
                                         fetch("__WB_BASE_PATH__/api/v1/records?" + query({doc_type: view, limit: LIMIT, voided: "only"}))]);
      if (!r.ok || !rv.ok) throw new Error(`HTTP ${r.ok ? rv.status : r.status}`);
      all = (await r.json()).records; voidedList = (await rv.json()).records;
      for (const id of [...selected]) if (!all.some(x => x.id === id && x.stage !== "approved")) selected.delete(id);
      $("#note").hidden = all.length < LIMIT;
      $("#note").textContent = `只显示了最近 ${LIMIT} 条。缩小日期范围可以看到更早的记录。`;
      drawDocs();
    }
  } catch (e) {
    $("#err").innerHTML = `读不到台账（${esc(e.message)}）。检查服务是否在运行，然后 <a href="#" id="retry">重试</a>。`;
    $("#err").hidden = false; $("#retry").onclick = ev => { ev.preventDefault(); load(); };
  }
  if (!keepOpen) closeDrawer(true);
  $("#upd").textContent = "更新于 " + new Date().toTimeString().slice(0, 5);
}
